def _numerals() -> Dict[str, int]:
    return {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}


def _require_roman(value: str) -> str:
    if not isinstance(value, str):
        raise TypeError("value must be a string")
    if value == "":
        raise ValueError("value must not be empty")
    return value.upper()


def _value_for(ch: str, numerals: Dict[str, int]) -> int:
    if ch not in numerals:
        raise ValueError("invalid Roman numeral character")
    return numerals[ch]


def roman_to_int(value: str) -> int:
    """Convert a Roman numeral containing I, V, X, L, C, D, M to an integer.

    Standard subtractive pairs are supported, so IV is 4 and IX is 9. Invalid
    characters raise ValueError.
    """
    text = _require_roman(value)
    numerals = _numerals()
    total = 0
    for ch in text:
        total += _value_for(ch, numerals)
    return total
"}

{"success": true, "content": "from typing import List


def _require_name(full_name: str) -> str:
    if not isinstance(full_name, str):
        raise TypeError("full_name must be a string")
    return full_name.strip()


def _split_name(full_name: str) -> List[str]:
    parts = []
    for raw_part in full_name.split():
        cleaned = raw_part.strip(" .")
        if cleaned:
            parts.append(cleaned)
    return parts


def _first_character(word: str) -> str:
    return word[0]


def make_initials(full_name: str) -> str:
    """Return uppercase initials for each non-empty word in a person's name.

    Words are separated by whitespace. Leading, trailing, and repeated
    whitespace should be ignored. The returned initials are separated by
    periods, so "ada lovelace" becomes "A.L".
    """
    normalized = _require_name(full_name)
    words = _split_name(normalized)
    initials = []
    for word in words:
        initials.append(_first_character(word).upper())
    return ".".join(initials)
"}

